export type TeamPalette = (typeof teamPaletteRegistry)[number];
const key = (value: string) => value.trim().toLocaleLowerCase().replace(/[^a-z0-9]+/g, "");
export function resolveTeamPalette(input: { sport: string; name: string; abbreviation?: string; competition?: string }): TeamPalette | undefined {
  const aliases = [input.name, input.abbreviation ?? ""].map(key).filter(Boolean);
  const competition = key(input.competition ?? "");
  return teamPaletteRegistry.find((palette) => key(palette.sport) === key(input.sport) && (!competition || key(palette.tournament) === competition) && aliases.some((alias) => [palette.name, palette.displayName, palette.abbreviation].map(key).includes(alias)))
    ?? teamPaletteRegistry.find((palette) => key(palette.sport) === key(input.sport) && aliases.some((alias) => [palette.name, palette.displayName, palette.abbreviation].map(key).includes(alias)));
}
